// Insert inserts the record into the database
func (t *BankAccount) Insert(runTrigger bool) bool {
	// OnInsert trigger of the business logic, then the field checks of the definition
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnInsert(); err != nil {
			fmt.Printf("Error: OnInsert trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}

	// A taken key inserts nothing (ON CONFLICT … DO NOTHING) instead of failing: on PostgreSQL
	// a failed INSERT would abort the transaction
	switch t.rec().Insert() {
	case tables.InsertFailed:
		return false
	case tables.KeyTaken:
		// INSERT fails in the classic way: "<Table> <key> already exists"
		_, key := t.recordKey()
		t.triggerErr = apperrors.TableRecordExists(BankAccountTableName, key)
		return false
	}
	// The record as written: its xRec from now on (a following Modify or Rename compares with it)
	t.StoreOldValues()
	return true
}

// InsertAll inserts records in bulk (demo data, imports): multi-row INSERT statements, one
// round trip per batch instead of one per record. With runTrigger every record's OnInsert
// trigger runs first, as Insert(true) would; the first failure stops before anything is
// written. Records are written with the receiver's database and company. Errors are
// *tables.BatchInsertError (Index = the record in records). Use it in a transaction: a
// failed batch leaves the earlier batches written.
func (t *BankAccount) InsertAll(records []*BankAccount, runTrigger bool) error {
	rows := make([][]interface{}, 0, len(records))
	for i, r := range records {
		r.triggerErr = nil
		if runTrigger {
			if err := r.runOnInsert(); err != nil {
				r.triggerErr = err
				return &tables.BatchInsertError{Index: i, Trigger: true, Err: err}
			}
		}
		rows = append(rows, bankAccountFields.RowValues(r.fieldRef))
	}
	tableName := fmt.Sprintf("%s$%s", t.company, BankAccountTableName)
	return tables.InsertRows(t.exec(), t.dbType, tableName, bankAccountFields.Columns(), rows)
}

// Modify updates the record in the database
func (t *BankAccount) Modify(runTrigger bool) bool {
	// OnModify trigger of the business logic, then the field checks of the definition
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnModify(); err != nil {
			fmt.Printf("Error: OnModify trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	// A changed primary key is a rename: run the OnRename trigger
	// before it is written; xRec values are available through OldValue
	keyChanged := bankAccountFields.KeyChanged(t.fieldRef, t.oldValues)
	if runTrigger && keyChanged {
		if err := t.runOnRename(); err != nil {
			fmt.Printf("Error: OnRename trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	// Renamed key fields that other tables refer to (Rename): carried over below
	type renamedKey struct {
		field    string
		old, new interface{}
	}
	var renamed []renamedKey
	if t.oldValues != nil {
		if t.hasFieldChanged("no") {
			renamed = append(renamed, renamedKey{"no", t.oldValues["no"], t.No})
		}
	}

	switch t.rec().Modify(t.oldValues) {
	case tables.ModifyFailed:
		return false
	case tables.NothingToSave:
		return true
	}
	// A temporary record's rename stays in the record: other tables are not changed
	for _, r := range renamed {
		if t.temp != nil {
			break
		}
		if err := t.renameReferences(r.field, r.old, r.new); err != nil {
			fmt.Printf("Error: Failed to rename references to Bank_Account: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	// The stored record now matches the current values (including a renamed key)
	if t.oldValues != nil {
		t.StoreOldValues()
	}
	return true
}

// hasFieldChanged checks if a field value has changed from oldValues
func (t *BankAccount) hasFieldChanged(fieldName string) bool {
	return bankAccountFields.Changed(t.fieldRef, t.oldValues, fieldName)
}

// SetDB changes the database executor of the record without touching its values — e.g. to
// run a Modify (with its rename cascade) inside a transaction.
func (t *BankAccount) SetDB(db database.Executor) {
	t.db = db
}

// renameReferences carries a renamed key over to every field of another table that refers
// to it (Rename). References from company tables are updated in this company — in
// every company when this table is global. Runs on the record's executor, so inside the
// caller's transaction.
func (t *BankAccount) renameReferences(field string, oldValue, newValue interface{}) error {
	type reference struct {
		table      string
		global     bool
		column     string
		condColumn string // a conditional relation: only rows whose condColumn = condValue
		condValue  int
	}
	references := map[string][]reference{
		"no": {{"Bank_Acc_Reconciliation", false, "bank_account_no", "", 0}, {"Bank_Acc_Reconciliation_Line", false, "bank_account_no", "", 0}, {"Bank_Account_Statement", false, "bank_account_no", "", 0}, {"Bank_Account_Statement_Line", false, "bank_account_no", "", 0}, {"Bank_Account_Ledger_Entry", false, "bank_account_no", "", 0}, {"Bank_Account_Ledger_Entry", false, "bal_account_no", "bal_account_type", 3}, {"Check_Ledger_Entry", false, "bank_account_no", "", 0}, {"Check_Ledger_Entry", false, "bal_account_no", "bal_account_type", 3}, {"Comment_Line", false, "no", "table_name", 8}, {"Customer Ledger Entry", false, "bal_account_no", "bal_account_type", 3}, {"FA_Ledger_Entry", false, "bal_account_no", "bal_account_type", 3}, {"Gen_Journal_Batch", false, "bal_account_no", "bal_account_type", 3}, {"Gen_Journal_Line", false, "account_no", "account_type", 3}, {"Gen_Journal_Line", false, "bal_account_no", "bal_account_type", 3}, {"Gen_Journal_Line", false, "source_no", "source_type", 3}, {"Gen_Journal_Template", false, "bal_account_no", "bal_account_type", 3}, {"G_L_Entry", false, "bal_account_no", "bal_account_type", 3}, {"G_L_Entry", false, "source_no", "source_type", 3}, {"Maintenance_Ledger_Entry", false, "bal_account_no", "bal_account_type", 3}, {"Payment_Method", false, "bal_account_no", "bal_account_type", 1}, {"Vendor Ledger Entry", false, "bal_account_no", "bal_account_type", 3}},
	}
	companies := []string{t.company}
	for _, ref := range references[field] {
		tables := []string{ref.table}
		if !ref.global {
			tables = tables[:0]
			for _, c := range companies {
				tables = append(tables, c+"$"+ref.table)
			}
		}
		for _, tbl := range tables {
			stmt := fmt.Sprintf(`UPDATE "%s" SET %s = ? WHERE %s = ?`, tbl, ref.column, ref.column)
			args := []interface{}{newValue, oldValue}
			if ref.condColumn != "" {
				stmt += fmt.Sprintf(" AND %s = ?", ref.condColumn)
				args = append(args, ref.condValue)
			}
			query := t.convertPlaceholders(stmt, len(args))
			if _, err := t.db.Exec(query, args...); err != nil {
				return fmt.Errorf("%s.%s: %w", tbl, ref.column, err)
			}
		}
	}
	return nil
}

// refuseDeleteWhenUsed: a record still refers to this one
func (t *BankAccount) refuseDeleteWhenUsed() error {
	return tables.RefuseDeleteWhenUsed(t.exec(), t.dbType, tables.DeletedRecord{
		Table: BankAccountTableName, Global: false, Company: t.company,
		KeyColumn: "no", Key: t.No, KeyText: fmt.Sprint(t.No),
	}, []tables.Reference{
		{Table: "Bank_Acc_Reconciliation", Column: "bank_account_no"},
		{Table: "Bank_Acc_Reconciliation_Line", Column: "bank_account_no"},
		{Table: "Comment_Line", Column: "no", CondColumn: "table_name", CondValue: 8},
		{Table: "Gen_Journal_Batch", Column: "bal_account_no", CondColumn: "bal_account_type", CondValue: 3},
		{Table: "Gen_Journal_Line", Column: "account_no", CondColumn: "account_type", CondValue: 3},
		{Table: "Gen_Journal_Line", Column: "bal_account_no", CondColumn: "bal_account_type", CondValue: 3},
		{Table: "Gen_Journal_Line", Column: "source_no", CondColumn: "source_type", CondValue: 3},
		{Table: "Gen_Journal_Template", Column: "bal_account_no", CondColumn: "bal_account_type", CondValue: 3},
		{Table: "Payment_Method", Column: "bal_account_no", CondColumn: "bal_account_type", CondValue: 1},
	})
}

// Delete removes the record from the database
func (t *BankAccount) Delete(runTrigger bool) bool {
	// OnDelete trigger of the business logic
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnDelete(); err != nil {
			fmt.Printf("Error: OnDelete trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
		// Refused while a record still refers to this one (refuse_delete_when_used)
		if t.temp == nil {
			if err := t.refuseDeleteWhenUsed(); err != nil {
				t.triggerErr = err
				return false
			}
		}
	}

	return t.rec().Delete()
}

